import { useMemo } from "react";

export type Locale = "zh" | "en";

/**
 * i18n copy for the site. This is a deep module: the interface is the
 * `useCopy()` hook and the `Locale`/`Copy` types; the implementation
 * holds the full bilingual copy. Pages never touch the raw object —
 * they ask for `t(key)` and get the localized string.
 *
 * Copy mirrors copy/zh.toml and copy/en.toml from the root repo. When
 * the toml changes, the generated `web/src/lib/copy.gen.ts` is
 * regenerated by `scripts/gen-copy.py` (run from web/).
 */
import { COPY, type Copy } from "./copy.gen";

export interface CopyApi {
  /** Current locale. */
  locale: Locale;
  /** The other locale (for the switch link). */
  other: Locale;
  /** Look up a copy key for the current locale. */
  t: (key: keyof Copy) => string;
  /** The current locale's raw copy object (for arrays/objects). */
  raw: Copy;
}

export function getCopy(locale: Locale): Copy {
  return COPY[locale];
}

/** React binding of the copy module. `locale` is a prop, not a global. */
export function useCopy(locale: Locale): CopyApi {
  const raw = useMemo(() => COPY[locale], [locale]);
  const other: Locale = locale === "zh" ? "en" : "zh";
  return {
    locale,
    other,
    t: (key) => raw[key] as string,
    raw,
  };
}
